using FreeSql;using VelrixWorkHub.Application.Lms;using VelrixWorkHub.Domain;namespace VelrixWorkHub.Infrastructure.Lms;
public sealed class FreeSqlLmsFeatureRepository(IFreeSql fsql):ILmsFeatureRepository{public IReadOnlyList<LmsFeature> List()=>fsql.Select<LmsFeatureRecord>().ToList().Select(x=>{var f=new LmsFeature(x.Code,x.Name,x.Description,x.OtherInfo,x.CreatedAt){Id=x.Id};f.SetStatus(x.Status);return f;}).ToArray();public void Add(LmsFeature x)=>fsql.Insert(new LmsFeatureRecord{Id=x.Id,Code=x.Code,Name=x.Name,Description=x.Description,OtherInfo=x.OtherInfo,Status=x.Status,CreatedAt=x.CreatedAt}).ExecuteAffrows();public void Update(LmsFeature x){if(fsql.Update<LmsFeatureRecord>().Set(a=>a.Status,x.Status).Where(a=>a.Id==x.Id).ExecuteAffrows()==0)throw new InvalidOperationException("特性不存在。");}}
